local _, NS = ...

-- locales/enUS.lua — the canonical locale (localization-§1). Loads FIRST in the TOC, ahead of
-- core/, so it bootstraps NS.L for every file after it.
--
-- The metatable returns the KEY on a miss, so a string routed before this file lists it still
-- renders in English and a partial translation degrades one string at a time rather than to nil.
-- Keys ARE the English source strings (localization-§2); a translation copies this file, gates it
-- with GetLocale() and changes only the right-hand sides.
--
-- GENERATED KEY SET: every `L["…"]` subscript in the addon's own source, plus the labels routed by
-- value (core/Constants.lua's *_LABELS tables and defaults/Categories.lua's labels and
-- descriptions). tests/test_locale.lua fails on a subscript missing here and on a key nothing uses.

NS.L = setmetatable(NS.L or {}, { __index = function(_, k) return k end })
local L = NS.L

